def count_pairs_sum(xs: list[int], t: int) -> int:
    """
    Count pairs of distinct positions i < j with xs[i] + xs[j] == t.

    pre: len(set(xs)) == len(xs)
    post: __return__ == _brute_pairs(xs, t)
    """
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    total = 0
    for a, ca in counts.items():
        b = t - a
        if a < b and b in counts:
            total += ca * counts[b]
        elif a == b:
            total += ca * (ca - 1) // 2
    return total

