def _is_prime_spec(n: int) -> bool:
    """Reference definition: n >= 2 and no d in [2, n) divides n."""
    return n >= 2 and all((n % d != 0 for d in range(2, n)))

def is_prime(n: int) -> bool:
    """Return whether n is a prime number.

    pre: n >= 2
    post: __return__ == _is_prime_spec(n)
    """
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

