def last_index_of(xs: list[int], x: int) -> int:
    """
    Return the 0-based index of the last occurrence of x in xs.

    pre: any(v == x for v in xs)
    post: 0 <= __return__ < len(xs) and xs[__return__] == x and all(xs[j] != x for j in range(__return__ + 1, len(xs)))
    """
    for i in range(len(xs) - 1, -1, -1):
        if xs[i] == x:
            return i
    raise ValueError('x is not in xs')

