def _run_lengths(xs: list[int]) -> list[int]:
    """Return the lengths of all maximal runs of equal consecutive elements in xs, in order."""
    lengths = []
    count = 0
    prev = None
    for i, x in enumerate(xs):
        if i > 0 and x == prev:
            count += 1
        else:
            if i > 0:
                lengths.append(count)
            count = 1
        prev = x
    if len(xs) > 0:
        lengths.append(count)
    return lengths

def longest_run(xs: list[int]) -> int:
    """
    Return the length of the longest run of equal consecutive elements in xs.

    pre: len(xs) >= 1
    post: __return__ == max(_run_lengths(xs))
    """
    best = 0
    cur = 0
    prev = None
    for i, x in enumerate(xs):
        if i > 0 and x == prev:
            cur += 1
        else:
            cur = 1
        if cur > best:
            best = cur
        prev = x
    return best

